    /*
     * Add to the Plans
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	InsurancePayer
     */
    public InsurancePayer addToPlans( UUID parentId, InsurancePlan addTo ) {
	    LOGGER.info("handling AssignPlansToInsurancePayerEvent - " );
	    
	    InsurancePayer parentEntity = repository.findById(parentId).get();
	    InsurancePlan child = registry.project( InsurancePlan.class, addTo.getInsurancePlanId());
	    
	    parentEntity.getPlans().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Plans
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	InsurancePayer
     */
	public InsurancePayer removeFromPlans( UUID parentId, InsurancePlan removeFrom ) {
	    LOGGER.info("handling RemovePlansFromInsurancePayerEvent " );
	
	    InsurancePayer parentEntity = repository.findById(parentId).get();
	    InsurancePlan child = registry.project( InsurancePlan.class, removeFrom.getInsurancePlanId());
	    
	    parentEntity.getPlans().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}

